entries[156763] = { ["name"] = "Racerfish Fin Tips", ["text"] = "Binds when picked up\nDuration: 5 min (real time)\n\"What sort of monster clipped the tips off a racerfish? You question whether you should be supporting such a heinous enterprise.\"" }
