entries[156770] = { ["name"] = "Super Slick Eel Slime", ["text"] = "Binds when picked up\nDuration: 5 min (real time)\n\"Eels have a monopoly on running the slip 'n' slides ate all the underocean birthday parties.\"" }
entries[156771] = { ["name"] = "Vantus Black Squid Ink", ["text"] = "Binds when picked up\nDuration: 5 min (real time)\n\"This ink is so black that it seems to be noticeably darkening the world around it.\"" }
entries[156772] = { ["name"] = "Extra-Sharp Pufferfish Quills", ["text"] = "Binds when picked up\nDuration: 5 min (real time)\n\"Still dripping with a powerful toxin that debilities both mind and body.\"\nSell Price:" }
entries[156773] = { ["name"] = "Accidentally-Severed Seahorse Fin", ["text"] = "Binds when picked up\nDuration: 5 min (real time)\n\"Someone should really do something about the razorcoral dangling from those low overhangs.\"" }
