entries[156776] = { ["name"] = "Makrura Eye", ["text"] = "Binds when picked up\nDuration: 5 min (real time)\n\"Makrura are easily distinguished from Lobstroks, and this unmistakably belonged to a Makrura. They're highly dissimilar, as everyone knows.\"\nSell Price:" }
entries[156777] = { ["name"] = "Lobstrok Eye", ["text"] = "Binds when picked up\nDuration: 5 min (real time)\n\"This clearly came from a Lobstrok, not a Makrura. The difference is obvious, and only a fool would confuse them.\"" }
