entries[156784] = { ["name"] = "Manta Ray Barb", ["text"] = "Binds when picked up\nDuration: 5 min (real time)\n\"The result of an unfortunate boating accident. At least you can put it to good use, right?\"\nSell Price:" }
entries[156785] = { ["name"] = "Threshadon Flipper", ["text"] = "Binds when picked up\nDuration: 5 min (real time)\n\"Pretty much all fish seem to hate the threshadons. Perhaps it's all of the devouring of their friends.\"" }
entries[156786] = { ["name"] = "Razoreel Larva", ["text"] = "Binds when picked up\nDuration: 5 min (real time)\n\"While it may seem appalling at first, it is customary amongst razoreel families to sell off the runt of each clutch, in order to serve as a warning to the other larva.\"" }
