entries[157861] = { ["name"] = "Skycaller Gem Chip", ["text"] = "Quest Item\nUnique (40)\n\"A faint shock of electricity runs through your fingers when holding this piece.\"" }
entries[157862] = { ["name"] = "Skycaller Gem Matrix", ["text"] = "Binds when picked up\nUnique\nUse: Uses 25 Skycaller Gem Chips to create a Skycaller Gem.\n\"A socket is inlaid into this device.\"" }
entries[157863] = { ["name"] = "Restored Skycaller Gem", ["text"] = "Quest Item\n\"Lightning crackles from within the depths of this gem.\"" }
entries[157864] = { ["name"] = "Glittering Sapphire", ["text"] = "Quest Item\n\"Shimmers and shines even in the dimmest light.\"" }
entries[157865] = { ["name"] = "Sulthis' Stone", ["text"] = "Quest Item\nUnique\n\"Smooth and cool to the touch.\"" }
entries[157866] = { ["name"] = "Invasion Plans", ["text"] = "Quest Item\n\"The orders, addressed to Overseer Zarjish, have been signed by Queen Azshara.\"\n<Right Click to Read>" }
entries[157867] = { ["name"] = "Mindbreaker Chant", ["text"] = "Quest Item\nUse: Perform the Mindbreaker Chant Zul taught you, releasing nearby Mindslaves from the effects of Zuvembi Brew. (3 Sec Cooldown)" }
entries[157870] = { ["name"] = "Zandalari Direhorn", ["text"] = "Binds when picked up\nUnique\nMount\n(Account-wide)\nRequires any Horde race\nUse: Teaches you how to summon this mount.\nSummons and dismisses your Zandalari Direhorn.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\"The Zandalari pride themselves on being the first to raise and train all of the most ferocious lizards on Azeroth.\"\nAchievement:\nAllied Races: Zandalari Troll" }
